var file_map = map[string]string{

	"clients.baml":      "client<llm> ViewCopilotClient {\n  provider anthropic\n  options {\n    model claude-opus-4-5-20251101\n    api_key env.ANTHROPIC_API_KEY\n  }\n}\n",
	"generators.baml":   "generator target {\n    output_type \"go\"\n    output_dir \"../\"\n    version \"0.218.1\"\n    on_generate \"bash \\\"$(git rev-parse --show-toplevel)/bin/patch-baml-runtime.sh\\\" && gofmt -w . && goimports -w .\"\n    client_package_name \"github.com/beam-cloud/airstore/pkg/views\"\n}\n",
	"map_outputs.baml":  "// =============================================================================\n// MapOutputsToSchema\n// Maps task outputs (grouped by task_id) into the column schema of a sheet's\n// table component. Multiple outputs from the same task can be synthesized into\n// one row or expanded into multiple rows, depending on the sheet's row strategy.\n// Called at view render time, results are cached.\n// =============================================================================\n\nclass ColumnSchema {\n  key string @description(\"Machine-stable column key, e.g. 'recipe_name', 'video_url'\")\n  type string @description(\"Column type: text, number, currency, date, link, email, status, tags, boolean\")\n  description string @description(\"Semantic description of what this column should contain, e.g. 'The name of the recipe', 'URL to the video'\")\n}\n\nclass MappedCell {\n  column string @description(\"Column key matching a ColumnSchema.key\")\n  value string @description(\"The extracted value as a string. Empty string if no value found.\")\n}\n\nclass MappedRow {\n  task_id string @description(\"The task ID this row was synthesized from\")\n  row_key string @description(\"Machine-stable identifier unique within the task group. Use 'task' for task-level rows. For split rows, derive it from the unique entity, like an email address, listing id, or contact slug.\")\n  source_output_ids string[] @description(\"The IDs of the outputs that most directly contributed to this row\")\n  cells MappedCell[] @description(\"MUST contain exactly one MappedCell for EVERY column in the schema. Never skip columns — use empty string value for missing data.\")\n}\n\nclass MappedResult {\n  rows MappedRow[] @description(\"One or more rows per task that have relevant data for this table\")\n}\n\nfunction MapOutputsToSchema(\n  sheet_name: string,\n  table_title: string,\n  table_type: string,\n  row_strategy_mode: string,\n  row_strategy_description: string,\n  columns: ColumnSchema[],\n  outputs_json: string\n) -> MappedResult {\n  client OutputMapperClient\n  prompt #\"\n    You are an extraction engine. Your job is to find values in task outputs\n    and map them into a table's column schema. Extract aggressively — your\n    goal is to fill as many cells as possible with real data from the outputs.\n\n    SHEET: {{ sheet_name }}\n    TABLE: {{ table_title }} (type: {{ table_type }})\n    ROW STRATEGY MODE: {{ row_strategy_mode }}\n    ROW STRATEGY DESCRIPTION: {{ row_strategy_description }}\n\n    COLUMN SCHEMA:\n    {% for col in columns %}\n    - {{ col.key }} ({{ col.type }}): {{ col.description }}\n    {% endfor %}\n\n    TASK OUTPUTS:\n    <outputs>{{ outputs_json }}</outputs>\n\n    WHERE TO FIND VALUES — search ALL of these for each column:\n    - output.title — often contains the main label or name\n    - output.summary — a text summary of what the output contains\n    - output.data.* — the richest source; look at ALL keys AND nested values\n    - output.uri — file or resource URLs\n    - output.output_type — the type/category of the output\n    - output.agent_name — which agent produced this output\n    - output.metadata — ALL metadata fields (deeplink, artifact_label, tags,\n      artifact_role, artifact_key, artifact_kind, and any other keys present)\n    - prompt — the user's original request, often contains source URLs or names\n    Search EVERY field in the output object — not just the ones listed above.\n\n    EXTRACTION RULES:\n    1. Each top-level key in the outputs JSON is a task_id. Search ALL outputs\n       within each task group thoroughly before deciding a column has no value.\n    2. CRITICAL: Every row's cells array MUST contain one MappedCell for EVERY\n       column listed in the COLUMN SCHEMA above. There are {{ columns|length }}\n       columns — so each row must have exactly {{ columns|length }} cells.\n       Use \"\" for columns where no value is found, but DO NOT skip columns.\n    3. Use semantic matching, not just literal field names. A column asking for\n       \"Contact Name\" could match data.name, data.full_name, data.recipient,\n       title, or even a name embedded in a summary string. Try hard to match.\n    4. When multiple outputs have a value for the same column, prefer outputs\n       with artifact_role \"primary\" over \"supporting\" or \"incidental\".\n    5. For link columns: check data.*, uri, metadata.deeplink, AND the prompt.\n       Match the semantically correct URL to each column.\n    6. Preserve original values. Don't summarize unless the column type needs\n       it (e.g. extracting a date). For tags, join with \", \". For booleans,\n       use \"true\" or \"false\". For dates, use ISO 8601.\n    7. Do NOT fabricate values. If after searching all outputs thoroughly you\n       genuinely cannot find a value for a column, use \"\". But exhaust all\n       options first — an empty cell should be rare, not the default.\n    8. Every row MUST include a task_id and row_key.\n    9. If a task's outputs have NO relevant data for ANY column in the schema,\n       OMIT that task entirely — do not emit an empty row. But if at least one\n       column can be filled, emit the row with all extractable values.\n\n    ROW STRATEGY:\n    - If mode is \"task\": produce ONE row per task_id that has relevant data.\n      Synthesize the best value for each column from any output in the group.\n      row_key = \"task\".\n    - If mode is \"split\": emit MULTIPLE rows per task_id. The description\n      tells you what entity each row represents (e.g. one row per email\n      recipient, per listing, per item). Use stable, slug-like row_key values\n      (e.g. \"alice-smith\", \"listing-42\"). If no distinct entities exist,\n      fall back to one row with row_key = \"task\".\n\n    SHEET CONTEXT: The sheet name \"{{ sheet_name }}\" gives context for\n    disambiguation (e.g. which URL or label to pick when multiple exist)\n    and for deciding whether a task is relevant to this sheet at all.\n    It must NOT suppress individual cell extraction — if a column has a\n    matching value in the outputs, extract it. Two sheets with the same\n    column must get the same value for the same task.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\nclient<llm> OutputMapperClient {\n  provider \"openai-generic\"\n  options {\n    base_url \"https://api.cerebras.ai/v1\"\n    api_key env.CEREBRAS_API_KEY\n    model \"gpt-oss-120b\"\n  }\n}",
	"view_copilot.baml": "// =============================================================================\n// View Copilot\n// Generates and iteratively edits View definitions (dynamic dashboards)\n// =============================================================================\n\nenum ViewUpdateType {\n  CONVERSATION     @description(\"Conversational reply only — no view or workspace changes\")\n  VIEW_CREATE      @description(\"Initial view creation — generate the full dashboard definition\")\n  LAYOUT_CHANGE    @description(\"Repositioned, resized, or reordered existing components\")\n  COMPONENT_ADD    @description(\"Added one or more new components to the view\")\n  COMPONENT_EDIT   @description(\"Modified an existing component's config, data source, or transform rules\")\n  COMPONENT_REMOVE @description(\"Removed one or more components from the view\")\n  DATA_REBIND      @description(\"Changed data sources or transform rules without changing layout\")\n  INFRASTRUCTURE   @description(\"Created or modified agents, skills, or assignments — view_content may also be updated\")\n}\n\nenum OperationType {\n  CREATE_AGENT  @description(\"Create a new agent profile in the workspace\")\n  UPDATE_AGENT  @description(\"Update an existing agent's configuration\")\n  CREATE_SKILL  @description(\"Write a new SKILL.md and install it\")\n  INSTALL_SKILL @description(\"Install an existing skill to the workspace\")\n  ASSIGN_SKILL  @description(\"Assign a skill to an agent\")\n}\n\nclass Operation {\n  type OperationType @description(\"The type of workspace mutation to perform\")\n  payload string @description(\"JSON payload with operation-specific fields. For CREATE_AGENT: {name, role, model?, skills?[]}. For UPDATE_AGENT: {agent_id, name?, role?, model?, skills?[]}. For CREATE_SKILL: {name, content}. For ASSIGN_SKILL: {agent_id, skill_name}. IMPORTANT: Do NOT include system_prompt — the system generates it automatically with proper Airstore context. model must be one of: 'claude-sonnet-4-6' (default, omit if unsure) or 'claude-opus-4-6'. role must be 1-2 words max (e.g. 'Research', 'Engineering', 'Outreach'). For CREATE_SKILL, content must be valid SKILL.md with YAML frontmatter (---\\\\nname: ...\\\\ndescription: ...\\\\n---).\")\n}\n\nclass ViewDraftResponse {\n  update_type ViewUpdateType @description(\"What kind of change this response represents\")\n  message string @description(\"Conversational response explaining what was done or asking for clarification\")\n  view_content string @description(\"The complete JSON view definition. Empty string when update_type is CONVERSATION.\")\n  operations Operation[] @description(\"Workspace mutations to execute (create agents, install skills, etc). Empty array when no infrastructure changes are needed.\")\n}\n\nfunction WriteView(\n  user_message: string,\n  conversation_history: string,\n  current_view: string,\n  workspace_context: string,\n  component_registry: string\n) -> ViewDraftResponse {\n  client ViewCopilotClient\n  prompt #\"\n    You are a workbook designer. You build Views — each view is a workbook of\n    tabbed sheets. Each sheet has one primary data table and optional actions.\n    Views aggregate data from AI agents into clean, scannable sheets.\n\n    =============================================================================\n    COMPONENT REGISTRY\n    =============================================================================\n    {{ component_registry }}\n\n    =============================================================================\n    VIEW DEFINITION SCHEMA\n    =============================================================================\n    A view definition is a JSON object:\n    {\n      \"name\": \"string — concise goal-oriented title (NEVER 'dashboard' or 'app')\",\n      \"description\": \"string — what this view tracks\",\n      \"agents\": [\"agent-id-1\", \"agent-id-2\"],\n      \"sheets\": [\n        {\n          \"id\": \"sheet-1\",\n          \"name\": \"Sheet Name\",\n          \"description\": \"string — what this sheet tracks\",\n          \"layout\": {\"columns\": 12},\n          \"relations\": [\n            {\n              \"id\": \"rel-1\",\n              \"name\": \"Optional relation name\",\n              \"to_sheet_id\": \"sheet-2\",\n              \"from_column\": \"task_id\",\n              \"to_column\": \"task_id\"\n            }\n          ],\n          \"components\": [\n            {\n              \"id\": \"c1\",\n              \"type\": \"table\",\n              \"title\": \"Component Title\",\n              \"position\": {\"col\": 0, \"row\": 0, \"colSpan\": 12, \"rowSpan\": 1},\n              \"dataSource\": {\n                \"agent_id\": \"single-agent-id\",\n                \"agent_ids\": [\"agent-1\", \"agent-2\"],\n                \"output_type\": \"json|file|email|link|text\",\n                \"time_range\": \"24h|7d|30d\",\n                \"row_strategy\": {\n                  \"mode\": \"task|split\",\n                  \"description\": \"For split mode, describe what one row represents. Example: one row per emailed contact.\"\n                },\n                \"transform\": [\n                  {\"column\": \"stable_key\", \"source\": \"data.field|title|metadata.key\", \"type\": \"text|number|currency|datetime|link|email|status|tags|boolean\"}\n                ]\n              },\n              \"config\": {}\n            },\n            {\n              \"id\": \"a1\",\n              \"type\": \"action\",\n              \"title\": \"Action Name\",\n              \"position\": {\"col\": 0, \"row\": 1, \"colSpan\": 4, \"rowSpan\": 1},\n              \"config\": {}\n            }\n          ]\n        }\n      ]\n    }\n\n    STRUCTURE RULES:\n    - STRONG DEFAULT: use ONE sheet. A single sheet handles most workflows.\n      Only add multiple sheets when the user explicitly asks for them OR the\n      workflow has genuinely distinct data domains (e.g. \"contacts\" vs \"emails\n      sent\" vs \"pricing comparisons\" are three separate entity types that\n      would clutter one table). When in doubt, use one sheet.\n    - Every sheet has exactly ONE table component. It is always full-width\n      (colSpan: 12) at position row 0.\n    - Action components are optional and belong to their sheet.\n    - Generate concise sheet names. Avoid generic names like \"Sheet 1\" unless the\n      user gave no meaningful distinction.\n    - Use relations when a row in one sheet should connect to rows in another\n      sheet through stable keys like task_id, email, company_id, listing_id, etc.\n    - NO sections, NO metrics, NO charts, NO task_list components.\n    - The canvas automatically renders assigned agents and live task counts\n      for the active sheet — you do NOT need to create components for those.\n\n    TRANSFORM RULES (semantic hints for the BAML mapper):\n    At render time a BAML mapper dynamically maps task output data into table\n    columns. Transform rules guide the mapping:\n    - column: machine-stable key (snake_case) for what the column shows.\n      Put the visible header in config.columns[].label.\n    - source: dot-path hint into task_output fields (e.g. \"data.recipe_name\",\n      \"title\", \"uri\"). Guidance, not rigid binding.\n    - type: text (default), number, currency, datetime, link, email, status,\n      tags, boolean. Guides both display and mapping.\n    - row_strategy.mode:\n      - \"task\" (default): synthesize one row per task. This is the strong\n        default — omit row_strategy entirely unless split is needed.\n      - \"split\": expand a single task into many rows when it produces multiple\n        distinct entities (e.g. 10 emails sent, 5 listings scraped). Each\n        entity becomes its own row in the table.\n    - row_strategy.description is REQUIRED for split mode. Describe what one\n      row represents clearly, e.g. \"one row per recipient email that was sent\".\n    - Use split mode when a user says things like \"track each email separately\",\n      \"one row per contact\", \"expand into individual items\", etc.\n\n    =============================================================================\n    WORKSPACE CONTEXT\n    =============================================================================\n    {{ workspace_context }}\n\n    =============================================================================\n    CONVERSATION CONTEXT\n    =============================================================================\n\n    {% if conversation_history != \"\" %}\n    Previous conversation:\n    {{ conversation_history }}\n    {% endif %}\n\n    {% if current_view != \"\" %}\n    Current view definition:\n    ---BEGIN VIEW---\n    {{ current_view }}\n    ---END VIEW---\n    {% endif %}\n\n    =============================================================================\n    USER REQUEST\n    =============================================================================\n    {{ user_message }}\n\n    =============================================================================\n    INSTRUCTIONS\n    =============================================================================\n    1. Read the user's request. Determine what kind of change is needed.\n\n    2. Set update_type appropriately:\n       - CONVERSATION: answering questions, asking for clarification\n       - VIEW_CREATE: building a new view from scratch\n       - LAYOUT_CHANGE: only repositioning/resizing components\n       - COMPONENT_ADD: adding new components\n       - COMPONENT_EDIT: modifying existing component config/data\n       - COMPONENT_REMOVE: removing components\n       - DATA_REBIND: changing data sources without layout changes\n       - INFRASTRUCTURE: creating/modifying agents or skills\n\n    3. If agents or skills need to be created, populate the operations array.\n       CRITICAL: Agent references in the view MUST use the kebab-case key\n       derived from the agent name (lowercase, spaces/underscores → hyphens).\n       Example: name \"Email Outreach\" → key \"email-outreach\". Use consistently.\n\n    4. In view_content, always provide the COMPLETE view definition JSON.\n       If update_type is CONVERSATION, set view_content to empty string \"\".\n       CRITICAL: The output MUST include ALL existing sheets, components,\n       columns, and relations from the current view — even ones you did not\n       modify. Users add sheets and columns manually outside the copilot.\n       Never drop, rename, or reorganize sheets the user did not ask to change.\n       Only omit a sheet if the user explicitly asks to remove it.\n\n    5. In message, briefly explain what you did (1-3 sentences).\n\n    6. Generate unique sheet IDs (`sheet-1`, `sheet-2`), relation IDs\n       (`rel-1`, `rel-2`), and component IDs (`c1`, `c2` for tables;\n       `a1`, `a2` for actions).\n\n    7. NAMING: Never use \"dashboard\" or \"app\" in the view name. Use short,\n       goal-oriented names (e.g. \"Outreach Pipeline\", \"Content Calendar\").\n\n    8. When creating transform rules, inspect the ARTIFACT DESCRIPTORS in\n       workspace_context. Use exact dot-path field names from schemas as\n       source hints. Keep transform[].column machine-stable and put the\n       visible header in config.columns[].label.\n\n    9. When no artifact schemas exist yet, define columns with descriptive\n       names and types. The BAML mapper resolves dynamically at render time.\n       Example: {\"column\": \"name\", \"source\": \"title\", \"type\": \"text\"}\n\n    10. Default to ONE sheet. Only add more sheets when the data genuinely\n        splits into distinct entity types that would be confusing in a single\n        table. When using split row_strategy on a sheet, that is usually\n        sufficient — you do NOT need a separate \"detail\" sheet for it.\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
}

